import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'trip-store',
  description:
    "Read and update the trip: itinerary + packing (trip.json) and the journal (journal.json). Call action:'status' for the shape of the trip; 'set_trip' with start / travellers / destination as the traveller tells you; 'plan_day' with date + plan; 'pack_add' / 'pack_check' for the packing list; 'journal_entry' during the trip.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'set_trip', 'plan_day', 'pack_add', 'pack_check', 'journal_entry', or 'itinerary'.",
      required: true,
    },
    date: {
      type: 'string',
      description: "The day being planned: 2026-09-14 once the dates are known, otherwise 'Day 1', 'Day 2', ...",
    },
    plan: {
      type: 'string',
      description:
        "The day in plain sentences, one per line: what the day is for, then a couple of alternatives, then the free time. No 'Anchor:' or 'Options:' labels.",
    },
    start: {
      type: 'string',
      description: "The departure date they gave: 2026-09-12 when they named a day, otherwise their words ('next spring'). Never choose one for them.",
    },
    travellers: { type: 'string', description: "Who is going: a number ('4') or a phrase ('two adults and a toddler')." },
    destination: { type: 'string', description: 'Where the trip goes.' },
    item: { type: 'string', description: 'Packing item name.' },
    id: { type: 'string', description: "Packing item id, e.g. 'pack-3'." },
    note: { type: 'string', description: 'Journal entry text.' },
  },
  outputs: {
    daysPlanned: { type: 'number', description: 'Days with a plan.' },
    unpacked: { type: 'number', description: 'Packing items still unpacked.' },
    summary: { type: 'string', description: 'The trip picture (or the itinerary).' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── trip-rules-start ──
// Pure derivations over the trip doc: countdown, day keys and itinerary rendering.

function plural(n, one, many) {
  return n + ' ' + (n === 1 ? one : many);
}

function daysUntil(dateStr, nowMs) {
  if (!/^\d{4}-\d{2}-\d{2}/.test(String(dateStr || ''))) return null;
  var when = Date.parse(dateStr);
  if (!isFinite(when)) return null;
  return Math.ceil((when - nowMs) / (24 * 60 * 60 * 1000));
}

// "2026-09-14T10:00" -> "2026-09-14"; "day 3" / "Day3" / "3" -> "Day 3".
function dayKey(raw) {
  var text = String(raw || '').trim();
  var iso = text.match(/^\d{4}-\d{2}-\d{2}/);
  if (iso) return iso[0];
  var numbered = text.match(/^(?:day\s*)?(\d{1,3})$/i);
  if (numbered) return 'Day ' + Number(numbered[1]);
  return text;
}

// Numbered days sort by number ("Day 10" after "Day 9"); dates sort as text.
function sortedDays(days) {
  return Object.keys(days).sort(function (a, b) {
    var na = a.match(/^Day (\d+)$/);
    var nb = b.match(/^Day (\d+)$/);
    if (na && nb) return Number(na[1]) - Number(nb[1]);
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

// "4 people" / "4 travellers" -> "4", so the board can say "4 travellers";
// a phrase ("two adults and a toddler") is kept as written.
function partyCount(raw) {
  var text = String(raw || '').trim();
  var counted = text.match(/^(\d{1,3})\s*(?:people|persons|travell?ers|adults|guests|of us)?$/i);
  return counted ? String(Number(counted[1])) : text;
}

function travellersLine(travellers) {
  var text = String(travellers || '').trim();
  if (!text) return '';
  if (/^\d+$/.test(text)) return plural(Number(text), 'traveller', 'travellers');
  return text;
}

function renderItinerary(days) {
  var keys = sortedDays(days);
  if (keys.length === 0) return 'No days planned yet.';
  return keys
    .map(function (d) {
      return d + ': ' + days[d];
    })
    .join('\n');
}

function tripLine(trip, unpackedCount, nowMs) {
  var start = daysUntil(trip.startDate, nowMs);
  var planned = Object.keys(trip.days || {}).length;
  var who = travellersLine(trip.travellers);
  var lead =
    start === null
      ? trip.startDate && trip.startDate !== 'soon'
        ? 'Leaving ' + trip.startDate + '. '
        : 'No departure date yet. '
      : start > 0
        ? plural(start, 'day', 'days') + ' until departure. '
        : start === 0
          ? 'Departure day! '
          : 'On the road (or home again). ';
  return (
    (who ? who + '. ' : '') +
    lead +
    plural(planned, 'day', 'days') + ' planned. Packing: ' +
    (unpackedCount === 0 ? 'all packed.' : plural(unpackedCount, 'item', 'items') + ' still unpacked.')
  );
}
// ── trip-rules-end ──

const TRIP_FILE = 'trip.json';
const packing = rosterStore(gezel.fs, 'packing.json', {
  stages: ['unpacked', 'packed'],
  idPrefix: 'pack',
});
const journal = logStore(gezel.fs, 'journal.json');

interface Trip {
  version: number;
  destination: string;
  startDate: string;
  travellers: string;
  days: Record<string, string>;
  updatedAt: string;
}

async function loadTrip(): Promise<Trip> {
  try {
    const parsed = JSON.parse(await gezel.fs.read(TRIP_FILE)) as Partial<Trip>;
    return {
      version: 1,
      destination: typeof parsed.destination === 'string' ? parsed.destination : '',
      startDate: typeof parsed.startDate === 'string' ? parsed.startDate : '',
      travellers: typeof parsed.travellers === 'string' ? parsed.travellers : '',
      days: parsed.days && typeof parsed.days === 'object' ? (parsed.days as Record<string, string>) : {},
      updatedAt: new Date().toISOString(),
    };
  } catch {
    return {
      version: 1,
      destination: '',
      startDate: '',
      travellers: '',
      days: {},
      updatedAt: new Date().toISOString(),
    };
  }
}

async function saveTrip(trip: Trip): Promise<void> {
  trip.updatedAt = new Date().toISOString();
  await gezel.fs.write(TRIP_FILE, `${JSON.stringify(trip, null, 2)}\n`);
}

const trip = await loadTrip();

if (input.action === 'set_trip') {
  if (!input.start && !input.travellers && !input.destination) {
    throw new Error("set_trip needs at least one of 'start', 'travellers', or 'destination'.");
  }
  if (input.start) trip.startDate = input.start.trim();
  if (input.travellers) trip.travellers = partyCount(input.travellers);
  if (input.destination) trip.destination = input.destination.trim();
  await saveTrip(trip);
} else if (input.action === 'plan_day') {
  if (!input.date || !input.plan) throw new Error("plan_day needs 'date' (YYYY-MM-DD, or 'Day 1') and 'plan'.");
  trip.days[dayKey(input.date)] = input.plan;
  await saveTrip(trip);
} else if (input.action === 'pack_add') {
  if (!input.item) throw new Error("pack_add needs 'item'.");
  await packing.add({ status: 'unpacked', fields: { name: input.item } });
} else if (input.action === 'pack_check') {
  let id = input.id;
  if (!id && input.item) {
    const wanted = input.item.toLowerCase();
    const matches = (await packing.list()).filter(
      (r) => String(r.fields.name ?? '').toLowerCase() === wanted,
    );
    if (matches.length === 1) id = matches[0]!.id;
  }
  if (!id) throw new Error("Pass 'id' (e.g. 'pack-3') or an exact packing 'item'.");
  await packing.transition(id, 'packed');
} else if (input.action === 'journal_entry') {
  if (!input.note) throw new Error("journal_entry needs 'note'.");
  await journal.append({ kind: 'entry', note: input.note });
} else if (input.action !== 'status' && input.action !== 'itinerary') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, set_trip, plan_day, pack_add, pack_check, journal_entry, or itinerary.`,
  );
}

const packItems = await packing.list();
const unpacked = packItems.filter((r) => r.status === 'unpacked').length;

gezel.output({
  daysPlanned: Object.keys(trip.days).length,
  unpacked,
  summary:
    input.action === 'itinerary' ? renderItinerary(trip.days) : tripLine(trip, unpacked, Date.now()),
});
